export type PageViewEvent = {
  path: string
  userAgent: string
  referrer: string | null
  timestamp: string
}

const ANALYTICS_ENDPOINT = process.env.ANALYTICS_ENDPOINT

export async function logPageView(event: PageViewEvent): Promise<void> {
  if (!ANALYTICS_ENDPOINT) {
    // No analytics service configured — log locally instead.
    console.log('[analytics] page view', event)
    return
  }

  try {
    const res = await fetch(ANALYTICS_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type: 'page_view', ...event }),
    })
    if (!res.ok) {
      console.error(`[analytics] failed to log page view: ${res.status}`)
    }
  } catch (error) {
    // Analytics failures should never affect the user.
    console.error('[analytics] failed to log page view', error)
  }
}

