import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from '@/app/lib/analytics'

export default async function Home() {
  // Request data must be read during render — calling headers() inside
  // the after() callback of a Server Component throws at runtime.
  const requestHeaders = await headers()
  const userAgent = requestHeaders.get('user-agent') ?? 'unknown'
  const referrer = requestHeaders.get('referer')

  // Runs after the response has been sent, so it never delays the page.
  after(async () => {
    await logPageView({
      path: '/',
      userAgent,
      referrer,
      timestamp: new Date().toISOString(),
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for stopping by!</p>
    </main>
  )
}

